	"github.com/spf13/cobra"
)

func newCleanCmd() *cobra.Command {
	var forceFlag bool
	var allFlag bool
	var dryRunFlag bool
	var sessionFlag string

	cmd := &cobra.Command{
		Use:   "clean",
		Short: "Clean up Entire session data",
		Long: `Clean up Entire session data for the current HEAD commit.

By default, cleans session state and shadow branches for the current HEAD:
  - Session state files (.git/entire-sessions/<session-id>.json)
  - Shadow branch (entire/<commit-hash>-<worktree-hash>)

Use --all to clean all Entire session data across the repository:
  - All session state files (.git/entire-sessions/)
  - All shadow branches
  - Temporary files (.entire/tmp/)
The entire/checkpoints/v1 branch itself is preserved.

Use --session <id> to clean a specific session only.

Without --force, prompts for confirmation before deleting.
Use --dry-run to preview what would be deleted without prompting.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()

			// Validate mutually exclusive flags
			if allFlag && sessionFlag != "" {
				return errors.New("--all and --session cannot be used together")
			}

			// Check if in git repository before initializing logging,
			// to avoid creating .entire/logs in arbitrary directories.
			if _, err := paths.WorktreeRoot(ctx); err != nil {
				return errors.New("not a git repository")
			}

			// Initialize logging
			logging.SetLogLevelGetter(GetLogLevel)
			if err := logging.Init(ctx, ""); err == nil {
				defer logging.Close()
			}

			if allFlag {
				return runCleanAll(ctx, cmd, forceFlag, dryRunFlag)
			}

			if sessionFlag != "" {
				strat := GetStrategy(ctx)
				return runCleanSession(ctx, cmd, strat, sessionFlag, forceFlag, dryRunFlag, "Clean", "cleaned")
			}

			return runCleanCurrentHead(ctx, cmd, forceFlag, dryRunFlag)
		},
	}

	cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Skip confirmation prompt and override active session guard")
	cmd.Flags().BoolVarP(&allFlag, "all", "a", false, "Clean all session data across the repository")
	cmd.Flags().BoolVarP(&dryRunFlag, "dry-run", "d", false, "Preview what would be deleted without deleting")
	cmd.Flags().StringVar(&sessionFlag, "session", "", "Clean a specific session by ID")

	return cmd
}

// runCleanCurrentHead cleans session data for the current HEAD commit.
func runCleanCurrentHead(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
	strat := GetStrategy(ctx)
	w := cmd.OutOrStdout()

	// Dry-run: show what would be cleaned
	if dryRun {
		return previewCurrentHead(ctx, w)
	}

	// Check for active sessions before cleaning
	if !force {
		activeSessions, err := activeSessionsOnCurrentHead(ctx)
		if err != nil {
			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not check for active sessions: %v\n", err)
			fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override.")
			return nil
		}
		if len(activeSessions) > 0 {
			fmt.Fprintln(cmd.ErrOrStderr(), "Active sessions detected on current HEAD:")
			for _, s := range activeSessions {
				fmt.Fprintf(cmd.ErrOrStderr(), "  %s (phase: %s)\n", s.SessionID, s.Phase)
			}
			fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override or wait for sessions to finish.")
			return nil
		}
	}

	// Prompt for confirmation
	if !force {
		var confirmed bool

		form := NewAccessibleForm(
			huh.NewGroup(
				huh.NewConfirm().
					Title("Clean session data for current HEAD?").
					Value(&confirmed),
			),
		)

		if err := form.Run(); err != nil {
			if errors.Is(err, huh.ErrUserAborted) {
				return nil
			}
			return fmt.Errorf("failed to get confirmation: %w", err)
		}

		if !confirmed {
			return nil
		}
	}

	if err := strat.Reset(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr()); err != nil {
		return fmt.Errorf("clean failed: %w", err)
	}

	return nil
}

// previewCurrentHead shows what would be cleaned for the current HEAD.
func previewCurrentHead(ctx context.Context, w io.Writer) error {
	repo, err := openRepository(ctx)
	if err != nil {
		return err
	}

	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}

	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("failed to get worktree path: %w", err)
	}
	worktreeID, err := paths.GetWorktreeID(worktreePath)
	if err != nil {
		return fmt.Errorf("failed to get worktree ID: %w", err)
	}

	shadowBranchName := checkpoint.ShadowBranchNameForCommit(head.Hash().String(), worktreeID)

	// Check if shadow branch exists
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, refErr := repo.Reference(refName, true)
	hasShadowBranch := refErr == nil

	// Find sessions for this commit
	strat := GetStrategy(ctx)
	sessions, err := strat.FindSessionsForCommit(ctx, head.Hash().String())
	if err != nil {
		sessions = nil
	}

	if !hasShadowBranch && len(sessions) == 0 {
		fmt.Fprintln(w, "Nothing to clean for current HEAD.")
		return nil
	}

	fmt.Fprint(w, "Would clean the following items:\n\n")

	if len(sessions) > 0 {
		fmt.Fprintf(w, "Session states (%d):\n", len(sessions))
		for _, s := range sessions {
			fmt.Fprintf(w, "  %s (checkpoints: %d)\n", s.SessionID, s.StepCount)
		}
		fmt.Fprintln(w)
	}

	if hasShadowBranch {
		fmt.Fprintf(w, "Shadow branch:\n  %s\n\n", shadowBranchName)
	}

	fmt.Fprintln(w, "Run without --dry-run to clean these items.")
	return nil
}

// runCleanSession handles the --session flag: clean/reset a single session.
// actionVerb is the capitalized verb (e.g., "Clean" or "Reset") and pastVerb
// is the past tense (e.g., "cleaned" or "reset") used in user-facing messages.
func runCleanSession(ctx context.Context, cmd *cobra.Command, strat *strategy.ManualCommitStrategy, sessionID string, force, dryRun bool, actionVerb, pastVerb string) error {
	// Verify the session exists
	state, err := strategy.LoadSessionState(ctx, sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session: %w", err)
	}
	if state == nil {
		return fmt.Errorf("session not found: %s", sessionID)
	}

	if dryRun {
		w := cmd.OutOrStdout()
		fmt.Fprintf(w, "Would %s session %s (phase: %s, checkpoints: %d)\n", strings.ToLower(actionVerb), sessionID, state.Phase, state.StepCount)
		return nil
	}

	if !force {
		var confirmed bool

		title := fmt.Sprintf("%s session %s?", actionVerb, sessionID)
		description := fmt.Sprintf("Phase: %s, Checkpoints: %d", state.Phase, state.StepCount)

		form := NewAccessibleForm(
			huh.NewGroup(
				huh.NewConfirm().
					Title(title).
					Description(description).
					Value(&confirmed),
			),
		)

		if err := form.Run(); err != nil {
			if errors.Is(err, huh.ErrUserAborted) {
				return nil
			}
			return fmt.Errorf("failed to get confirmation: %w", err)
		}

		if !confirmed {
			return nil
		}
	}

	if err := strat.ResetSession(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionID); err != nil {
		return fmt.Errorf("%s session failed: %w", strings.ToLower(actionVerb), err)
	}

	fmt.Fprintf(cmd.OutOrStdout(), "Session %s has been %s. File changes remain in the working directory.\n", sessionID, pastVerb)
	return nil
}

// runCleanAll cleans all session data across the repository.
func runCleanAll(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {

package paths

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
	"sync"
	"unicode"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
)

// Directory constants
const (
	EntireDir         = ".entire"
	EntireTmpDir      = ".entire/tmp"
	EntireMetadataDir = ".entire/metadata"

	osWindows = "windows"
)

// Metadata file names
const (
	PromptFileName                = "prompt.txt"
	TranscriptFileName            = "full.jsonl"
	TranscriptFileNameLegacy      = "full.log"
	CompactTranscriptFileName     = "transcript.jsonl"
	CompactTranscriptHashFileName = "transcript_hash.txt"
	V2RawTranscriptFileName       = "raw_transcript"
	V2RawTranscriptHashFileName   = "raw_transcript_hash.txt"
	MetadataFileName              = "metadata.json"
	CheckpointFileName            = "checkpoint.json"
	ContentHashFileName           = "content_hash.txt"
	SettingsFileName              = "settings.json"
)

// MetadataBranchName is the orphan branch used by manual-commit strategy to store metadata
const MetadataBranchName = "entire/checkpoints/v1"

// V2 ref names use custom refs under refs/entire/ (not refs/heads/).
// These are invisible in GitHub's branch UI and not fetched by default.
const (
	// V2MainRefName stores permanent metadata + compact transcripts.
	V2MainRefName = "refs/entire/checkpoints/v2/main"

	// V2FullCurrentRefName stores the active generation of raw transcripts.
	V2FullCurrentRefName = "refs/entire/checkpoints/v2/full/current"

	// V2FullRefPrefix is the common prefix for all /full/* refs (current + archived).
	V2FullRefPrefix = "refs/entire/checkpoints/v2/full/"

	// GenerationFileName is the metadata file at the root of each /full/* generation tree.
	GenerationFileName = "generation.json"
)

// TrailsBranchName is the orphan branch used to store trail metadata.
// Trails are branch-centric work tracking abstractions that link to checkpoints by branch name.
const TrailsBranchName = "entire/trails/v1"

// CheckpointPath returns the sharded storage path for a checkpoint ID.
// Uses first 2 characters as shard (256 buckets), remaining as folder name.
// Example: "a3b2c4d5e6f7" -> "a3/b2c4d5e6f7"
//
// Deprecated: Use checkpointID.Path() directly instead.
func CheckpointPath(checkpointID id.CheckpointID) string {
	return checkpointID.Path()
}

// worktreeRootCache caches the worktree root to avoid repeated git commands.
// The cache is keyed by the current working directory to handle directory changes.
var (
	worktreeRootMu       sync.RWMutex
	worktreeRootCache    string
	worktreeRootCacheDir string
)

// WorktreeRoot returns the git worktree root directory.
// Uses 'git rev-parse --show-toplevel' which returns the working tree toplevel.
// In a worktree this is the worktree root, not the main repository root.
// The result is cached per working directory.
// Returns an error if not inside a git repository.
func WorktreeRoot(ctx context.Context) (string, error) {
	// Get current working directory to check cache validity
	cwd, err := os.Getwd() //nolint:forbidigo // already present in codebase
	if err != nil {
		cwd = ""
	}

	// Check cache with read lock first
	worktreeRootMu.RLock()
	if worktreeRootCache != "" && worktreeRootCacheDir == cwd {
		cached := worktreeRootCache
		worktreeRootMu.RUnlock()
		return cached, nil
	}
	worktreeRootMu.RUnlock()

	// Cache miss - get worktree root and update cache with write lock
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get git worktree root: %w", err)
	}

	root := strings.TrimSpace(string(output))

	worktreeRootMu.Lock()
	worktreeRootCache = root
	worktreeRootCacheDir = cwd
	worktreeRootMu.Unlock()

	return root, nil
}

// ClearWorktreeRootCache clears the cached worktree root.
// This is primarily useful for testing when changing directories.
func ClearWorktreeRootCache() {
	worktreeRootMu.Lock()
	worktreeRootCache = ""
	worktreeRootCacheDir = ""
	worktreeRootMu.Unlock()
}

// AbsPath returns the absolute path for a relative path within the repository.
// If the path is already absolute, it is returned as-is.
// Uses WorktreeRoot() to resolve paths relative to the worktree root.
func AbsPath(ctx context.Context, relPath string) (string, error) {
	if filepath.IsAbs(relPath) {
		return relPath, nil
	}

	root, err := WorktreeRoot(ctx)
	if err != nil {
		return "", err
	}

	return filepath.Join(root, relPath), nil
}

// IsInfrastructurePath returns true if the path is part of CLI infrastructure
// (i.e., inside the .entire directory)
func IsInfrastructurePath(path string) bool {
	return IsSubpath(EntireDir, path)
}

// IsSubpath reports whether child is lexically under parent (or equal to it).
// It uses filepath.Rel, which cleans both inputs and is traversal-resistant:
// a crafted child like "/a/b/../../../etc/passwd" that escapes parent will
// produce a relative path starting with ".." and be rejected.
func IsSubpath(parent, child string) bool {
	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

// ToRelativePath converts an absolute path to relative.
// Returns empty string if the path is outside the working directory.
func ToRelativePath(absPath, cwd string) string {
	absPath = normalizeMSYSPath(absPath)
	cwd = normalizeMSYSPath(cwd)

	// On Windows, MSYS/Git Bash sometimes omits the drive letter, producing
	// paths like /Users/... that filepath.IsAbs doesn't recognize. Prepend
	// the drive letter from cwd so filepath.Rel can match them.
	if runtime.GOOS == osWindows && len(absPath) > 0 && absPath[0] == '/' && len(cwd) >= 2 && cwd[1] == ':' {
		absPath = cwd[:2] + absPath
	}

	if !filepath.IsAbs(absPath) {
		return absPath
	}
	relPath, err := filepath.Rel(cwd, absPath)
	if err != nil || strings.HasPrefix(relPath, "..") {
		return ""
	}

	return relPath
}

// normalizeMSYSPath converts MSYS/Git Bash-style paths (e.g., /c/Users/...)
// to Windows-style paths (e.g., C:/Users/...) so that filepath.IsAbs and
// filepath.Rel work correctly. On non-Windows platforms this is a no-op.
// Claude Code on Windows outputs MSYS paths in its transcript, but Go's
// filepath package only recognizes Windows-style absolute paths.
func normalizeMSYSPath(p string) string {
	if runtime.GOOS != osWindows {
		return p
	}
	// MSYS paths look like /c/Users/... where the second char is a drive letter
	if len(p) >= 3 && p[0] == '/' && unicode.IsLetter(rune(p[1])) && p[2] == '/' {
		return string(unicode.ToUpper(rune(p[1]))) + ":" + p[2:]
	}
	return p
}

// nonAlphanumericRegex matches any non-alphanumeric character
var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)

// SanitizePathForClaude converts a path to Claude's project directory format.
// Claude replaces any non-alphanumeric character with a dash.
func SanitizePathForClaude(path string) string {
	return nonAlphanumericRegex.ReplaceAllString(path, "-")
}

// GetClaudeProjectDir returns the directory where Claude stores session transcripts
// for the given repository path.
//
// In test environments, set ENTIRE_TEST_CLAUDE_PROJECT_DIR to override the default location.
func GetClaudeProjectDir(repoPath string) (string, error) {
	override := os.Getenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR")
	if override != "" {
		return override, nil
	}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// DefaultMaxCheckpointsPerGeneration is the rotation threshold.
// When a generation reaches this many checkpoints, it is archived
// and a fresh /full/current is created.
const DefaultMaxCheckpointsPerGeneration = 100

// GenerationMetadata tracks the state of a /full/* generation.
// Written to the tree root as generation.json at archive time only — not during
// normal writes to /full/current. This keeps /full/current free of root-level
// files, ensuring conflict-free tree merges during push recovery.
//
// The generation's sequence number is derived from the ref name, not stored here.
// Checkpoint membership is determined by walking the tree (shard directories).
type GenerationMetadata struct {
	// OldestCheckpointAt is the creation time of the earliest checkpoint.
	OldestCheckpointAt time.Time `json:"oldest_checkpoint_at"`

	// NewestCheckpointAt is the creation time of the most recent checkpoint.
	NewestCheckpointAt time.Time `json:"newest_checkpoint_at"`
}

// ReadGeneration reads generation.json from the given tree hash.
// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
func (s *V2GitStore) ReadGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
	if treeHash == plumbing.ZeroHash {
		return GenerationMetadata{}, nil
	}

	tree, err := s.repo.TreeObject(treeHash)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
	}

	file, err := tree.File(paths.GenerationFileName)
	if err != nil {
		if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
			return GenerationMetadata{}, nil
		}
		return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
	}

	content, err := file.Contents()
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
	}

	var gen GenerationMetadata
	if err := json.Unmarshal([]byte(content), &gen); err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
	}

	return gen, nil
}

// ReadGenerationFromRef reads generation.json from the tree pointed to by the given ref.
func (s *V2GitStore) ReadGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
	_, treeHash, err := s.GetRefState(refName)
	if err != nil {
		return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
	}
	return s.ReadGeneration(treeHash)
}

// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
// Returns a TreeEntry ready to be placed in a tree.
func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
	}

	blobHash, err := CreateBlobFromContent(s.repo, data)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
	}

	return object.TreeEntry{
		Name: paths.GenerationFileName,
		Mode: filemode.Regular,
		Hash: blobHash,
	}, nil
}

// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
	entry, err := s.marshalGenerationBlob(gen)
	if err != nil {
		return err
	}
	entries[paths.GenerationFileName] = entry
	return nil
}

